#!/usr/bin/env bash
# tools/dist/build-ca-certs.sh — build the image TLS trust store (R7-Q2).
#
# Produces:  tools/dist/out/ca-certificates-20260611-r0.linux-<arch>.tar.gz
#            (etc/ssl/certs/ca-certificates.crt, etc/ssl/certs/*.0 hashed
#             symlinks, etc/ssl/cert.pem)
#
# The pinned Alpine ca-certificates apk is downloaded and its mozilla bundle
# extracted. The /etc/ssl/certs tree is then generated deterministically the
# same way update-ca-certificates does it:
#   1. concatenate the certs listed in /etc/ca-certificates.conf into
#      ca-certificates.crt;
#   2. `openssl rehash` the certs dir to create the hashed .0 symlinks;
#   3. symlink etc/ssl/cert.pem -> certs/ca-certificates.crt.
# Same cert set + SOURCE_DATE_EPOCH => byte-identical output.
#
# Needs no root when the host has openssl; the pipeline's CI/ops host (alpine
# or the build box) satisfies this.
#
# Usage:
#   tools/dist/build-ca-certs.sh [OUT_DIR]   # default tools/dist/out

set -euo pipefail

DIST_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=tools/dist/versions.sh
source "${DIST_DIR}/versions.sh"
# shellcheck source=tools/dist/lib.sh
source "${DIST_DIR}/lib.sh"

PRODUCT="ca-certs"
OUT_DIR="${1:-${DIST_DIR}/out}"

require_cmd curl
require_cmd tar
require_cmd openssl

# 1. Fetch the pinned apk and verify its sha256.
WORK="$(mktemp -d "${DIST_DIR}/.work-ca-certs.XXXXXX")"
trap 'rm -rf "${WORK}"' EXIT
apk_file="${WORK}/ca-certificates-${CA_CERTS_VERSION}.apk"
download "${CA_CERTS_APK_URL}" "${apk_file}" "${CA_CERTS_SHA256}"

# 2. Extract the apk (an apk is a gzip tar with .PKGINFO etc.).
tar -xzf "${apk_file}" -C "${WORK}" \
    || die "failed to extract ${CA_CERTS_PACKAGE} apk"
[[ -d "${WORK}/usr/share/ca-certificates/mozilla" ]] \
    || die "mozilla cert bundle missing from the apk"

# 3. Assemble the bundle + hashed /etc/ssl/certs from the mozilla certs.
#    update-ca-certificates semantics: each enabled cert appears in
#    /etc/ssl/certs as a <name>.crt symlink into /usr/share/ca-certificates;
#    the concatenated bundle is ca-certificates.crt; rehash then adds the
#    openssl HASH.0 lookup symlinks.
root="${WORK}/root"
mkdir -p "${root}/etc/ssl/certs" "${root}/usr/share/ca-certificates"
cp -a "${WORK}/usr/share/ca-certificates/mozilla" "${root}/usr/share/ca-certificates/"
cp -a "${WORK}/etc/ca-certificates.conf" "${root}/etc/ca-certificates.conf"
: > "${root}/etc/ssl/certs/ca-certificates.crt"
while IFS= read -r cert; do
    # Skip blank lines and comments (the conf file is generated by the apk).
    case "${cert}" in
        ""|\#*) continue ;;
    esac
    src="${root}/usr/share/ca-certificates/${cert}"
    [[ -f "${src}" ]] || die "cert listed in ca-certificates.conf not found: ${cert}"
    ln -s "/usr/share/ca-certificates/${cert}" "${root}/etc/ssl/certs/$(basename "${cert}")"
    cat "${src}" >> "${root}/etc/ssl/certs/ca-certificates.crt"
    printf '\n' >> "${root}/etc/ssl/certs/ca-certificates.crt"
done < "${root}/etc/ca-certificates.conf"

# Hashed lookup symlinks (HASH.0) — the naming used by openssl/update-ca-certificates.
openssl rehash "${root}/etc/ssl/certs" 2>/dev/null \
    || die "openssl rehash failed on ${root}/etc/ssl/certs"
ln -sf ca-certificates.crt "${root}/etc/ssl/cert.pem"

# 4. Verify the trust store is present, then assemble the deterministic tarball.
[[ -s "${root}/etc/ssl/certs/ca-certificates.crt" ]] \
    || die "ca-certificates.crt is empty after assembly"
[[ -L "${root}/etc/ssl/cert.pem" ]] \
    || die "etc/ssl/cert.pem missing after assembly"

mkdir -p "${OUT_DIR}"
stage="$(mktemp -d "${DIST_DIR}/.stage-ca-certs.XXXXXX")"
trap 'rm -rf "${WORK}" "${stage}"' EXIT
cp -a "${root}/etc" "${stage}/etc"

asset="${OUT_DIR}/$(product_asset_name ca-certificates "${CA_CERTS_VERSION}")"
tar_reproducible "${asset}" "${stage}"
echo "gitd: ca-certs: ${asset}"
echo "gitd: ca-certs: sha256 $(sha256_of "${asset}")"